  <p class="nd-guide" role="status">{{ announcement || guidance }}</p>
  <div class="nd-layout">
   <aside class="nd-drafts" aria-label="Fictional note drafts"><h3>Started drafts <span>3</span></h3><button v-for="(note,index) in narrivaExamples" :key="note.id" type="button" :aria-pressed="selected===index" @click="choose(index)" data-analytics-id="narriva-draft" data-analytics-label="Open a fictional Narriva draft"><strong>{{ note.name }}</strong><span>{{ note.focus }}</span><small>{{ note.date }} · Draft example</small></button><p>Choose another fictional client to explore a different session.</p></aside>
   <div class="nd-main">
    <div class="nd-note-header"><div><p>{{ example.name }} · {{ example.date }}</p><h3>{{ view==='work'?'Supervisor My Work':view==='sign'?'Review before signing':view==='check'?'Narriva Compliance':example.encounter.serviceCode==='90847'?'Couples therapy progress note':'Individual therapy progress note' }}</h3><span>{{ example.encounter.serviceCode }} · {{ example.encounter.durationMinutes }} minutes · {{ example.encounter.setting }}<small v-if="example.encounter.funding.includes('Self-pay')"> · {{ example.encounter.funding }}</small></span></div><span class="nd-status">{{ supervisorSigned?'Co-sign simulated':providerSigned?'Provider signature simulated':'Draft example' }}</span></div>
    <template v-if="view==='note'">
     <NarrivaModeChooser v-model="method" :compact="compact" @save-default="announce('Writing preference changed in this example only.')" />
     <div v-if="method==='manual'" class="nd-manual"><p class="nd-example-notice">{{ NARRIVA_DEMO_INPUT_NOTICE }}</p><label v-for="section in sections" :key="section.key">{{ section.label }}<textarea rows="5" readonly value="" :aria-label="`Blank manual ${section.label}`" placeholder="Blank manual writer · demonstration only" @focus="announce(NARRIVA_DEMO_INPUT_NOTICE)" @click="announce(NARRIVA_DEMO_INPUT_NOTICE)" /></label></div>
     <SmartNotesDemo v-else-if="method==='smart_notes'" @entry-attempt="announce(NARRIVA_DEMO_INPUT_NOTICE)" />
     <template v-else>
      <section class="nd-plan" aria-label="Seeded treatment plan"><header><div><span class="nd-eyebrow">TREATMENT CONTEXT · FICTIONAL</span><h4>{{ example.plan.title }}</h4></div><span>3 goals · Weekly</span></header><p><strong>Presenting concern:</strong> {{ example.presentingProblem }}</p><p><strong>Illustrative diagnostic context:</strong> {{ example.diagnosis }}</p><p class="nd-example-notice">{{ NARRIVA_DEMO_SOURCE_DISCLOSURE }} Ratings selected here demonstrate the controls; they do not rewrite the supplied session or establish measured improvement.</p>
       <label class="nd-attest"><input v-model="planReviewed" type="checkbox" @change="invalidate"/>Use this seeded treatment plan for the demonstration.</label>
       <NoteAidObjectiveRatings :key="ratingKey" :goals="example.plan.goals" :previous-ratings="previousRatings" date-of-service="2026-11-06" :client-name="example.name" collapsible-objectives read-only-text @update:ratings="updateRatings" @text-entry-attempt="announce(NARRIVA_DEMO_INPUT_NOTICE)"><template #goal-context="{goal}"><details class="nd-goal-context"><summary>Interventions &amp; timeframe</summary><ul><li v-for="intervention in goal.interventions" :key="intervention">{{ intervention }}</li></ul><p>{{ goal.timeframe }}</p></details></template></NoteAidObjectiveRatings>
       <details class="nd-discharge"><summary>Discharge plan</summary><p>{{ example.plan.dischargePlan }}</p></details>
       <p class="nd-requirement" role="status">{{ ready ? 'Plan reviewed and all three example objectives rated. Ready to demonstrate generation.' : 'Before generation: review the seeded plan and choose a sample rating or status for each of the three objectives.' }}</p>
      </section>
      <section class="nd-source"><h4>Session Narrative</h4><p>Read-only source for {{ example.name }}. Added encounter and safety details are explicitly fictional demo context.</p><textarea readonly :value="example.source" rows="10" aria-label="Fictional Session Narrative" @click="announce(NARRIVA_DEMO_INPUT_NOTICE)" @focus="announce(NARRIVA_DEMO_INPUT_NOTICE)"/><p class="nd-privacy">In the app, review your actual session source and applicable consent before generating a draft. This demonstration sends no data.</p><button type="button" class="nd-generate" :disabled="!ready||busy" @click="generateNote" data-analytics-id="narriva-generate" aria-label="Narriva Generate Note"><img :src="NARRIVA_BRAND.generate" alt="Narriva Generate Note"/><span v-if="busy">Demonstrating…</span></button></section>
      <div v-if="generated" class="nd-output" data-analytics-area="note-editor"><div class="nd-output-label"><span>Prepared Narriva draft · clinician review required</span><button type="button" :disabled="!generated" @click="view='summary'" data-analytics-id="narriva-summary">View summary →</button></div><article v-for="section in sections" :key="section.key"><h4>{{ section.label }}</h4><p>{{ section.text }}</p></article></div>

     <div v-if="generated" class="nd-next"><button type="button" class="nd-primary" @click="navigate('check')">View the five checks</button><button v-if="passed&&!providerSigned" type="button" class="nd-secondary" @click="beginSignature('provider')">Review and sign (demo)</button><span>Prepared example only. No AI request or actual signature.</span></div>
     </template>
    </template>
    <template v-else-if="view==='check'">
     <template v-if="!generated&&!busy"><p class="nd-example-notice">Start with the seeded plan and read-only Session Narrative. Generate the prepared note to watch the five example checks.</p><button type="button" class="nd-primary" @click="navigate('note')">Go to Session Narrative</button></template>
     <template v-else>
     <div class="nd-scenarios" role="group" aria-label="Choose an illustrative check outcome"><button type="button" :aria-pressed="scenario==='pass'" @click="changeScenario('pass')" :disabled="busy" data-analytics-id="narriva-pass">Complete note</button><button type="button" :aria-pressed="scenario==='needs-review'" @click="changeScenario('needs-review')" :disabled="busy" data-analytics-id="narriva-fail">{{ scenario==='needs-review'&&corrected?'Missing plan · corrected':'Missing follow-up plan' }}</button></div>
     <p class="nd-explanation">{{ corrected?'This sample includes the specific plan from the session source.':'This sample’s plan only says “Continue therapy.” Run the example check to see the finding, then apply the source-supported correction.' }}</p>
     <button type="button" class="nd-primary nd-run" :disabled="busy" @click="runChecks" data-analytics-id="narriva-check">{{ busy?'Showing the five checks…':'Run example note check' }}</button>
     <NarrivaCompliancePanel :review="review" :busy="busy" @retry="runChecks" @action="applyCorrection" />
     <div v-if="generated&&!busy" class="nd-output"><div class="nd-output-label"><span>Prepared SOIP note · demonstration only</span></div><article v-for="section in sections" :key="section.key"><h4>{{ section.label }}</h4><p>{{ section.text }}</p></article></div>
     <div v-if="generated" class="nd-next"><button type="button" class="nd-secondary" @click="navigate('note')">View generated SOIP note →</button></div>
     <div v-if="passed" class="nd-next"><button type="button" class="nd-primary" @click="beginSignature('provider')" :disabled="providerSigned" data-analytics-id="narriva-sign-review">{{ providerSigned?'Provider signature simulated':'Review and sign (demo)' }}</button><button type="button" class="nd-secondary" @click="navigate('work')" data-analytics-id="narriva-work">See My Work Quick Sign →</button></div>
    </template>
    </template>
    <template v-else-if="view==='work'">
     <div class="nd-person"><img src="/assets/schoolcarebridge/demo-tessa.png" alt="Fictional portrait of Dr. Tessa Brooks" loading="lazy" width="46" height="58"/><div><strong>Dr. Tessa Brooks, PhD</strong><span>Clinical supervisor · Notes to co-sign</span></div></div>
     <p class="nd-explanation">A provider-signed note with a current Narriva pass can offer Quick Sign in My Work. It still opens explicit review and attestation. Try Quick look on hover, focus or tap, and open Treatment history.</p>
     <article class="nd-work-card"><header><div><strong>{{ example.name }}</strong><span>{{ example.provider.name }}, {{ example.provider.credential }} · {{ example.date }} · {{ example.encounter.serviceCode }}</span></div><span>{{ supervisorSigned?'Co-sign simulated':passed&&providerSigned?'Ready for co-sign review':'Review required' }}</span></header><p v-if="!providerSigned">First complete the example note check and simulate the provider’s signature.</p><img v-if="passed&&providerSigned&&!supervisorSigned" class="nd-quick-badge" :src="NARRIVA_BRAND.quickSign" alt="Illustrative Narriva Quick Sign Approved"/><NoteReviewActions :key="`${example.id}:${revision}`" :item="workItem" :load-insights="loadInsights" allow-quick-sign @open-note="view='note'" @quick-sign="beginSignature('supervisor')" /></article>
     <button v-if="!providerSigned" type="button" class="nd-secondary" @click="navigate('check')">Return to note check</button>
     <p v-if="supervisorSigned" class="nd-success" role="status">Supervisor signature simulated. No actual note was co-signed, completed or submitted.</p>
    </template>
    <template v-else-if="view==='summary'&&generated"><p class="nd-explanation">The app’s saved-note summary, using the supplied fictional SOIP narrative. No session artifact is claimed for these cases.</p><NarrivaNoteSummary :quick-look="insights.quickLook" :source-revision="insights.sourceRevision" @open-note="view='note'"/><button type="button" class="nd-secondary" @click="view='note'">Back to note</button></template>
    <template v-else-if="view==='history'"><p class="nd-explanation">The app’s treatment-history view, with five fictional visits. Clinician objective ratings stay separate from client-reported check-ins.</p><NarrivaTreatmentHistory :history="insights.treatmentHistory"/></template>
    <template v-else-if="view==='sign'&&generated">
     <div class="nd-person"><img :src="signer==='supervisor'?'/assets/schoolcarebridge/demo-tessa.png':example.provider.photo" alt="Fictional staff portrait" loading="lazy" width="46" height="58"/><div><strong>{{ signer==='supervisor'?'Dr. Tessa Brooks, PhD':`${example.provider.name}, ${example.provider.credential}` }}</strong><span>{{ signer==='supervisor'?'Supervisor co-sign review':'Provider signature review' }} · Demonstration only</span></div></div>
     <p class="nd-success">Illustrative checks passed. Review the full note below before simulating a signature.</p><article v-for="section in sections" :key="section.key" class="nd-sign-section"><h4>{{ section.label }}</h4><p>{{ section.text }}</p></article>
     <label class="nd-attest"><input v-model="attested" type="checkbox" data-analytics-id="narriva-attest"/>I reviewed this fictional note. Simulate my {{ signer==='supervisor'?'co-signature':'provider signature' }}.</label>
     <div class="nd-next"><button type="button" class="nd-primary" :disabled="!attested||!passed||busy" @click="finishSignature" data-analytics-id="narriva-sign">{{ signer==='supervisor'?'Simulate Quick Sign':'Simulate provider signature' }}</button><button type="button" class="nd-secondary" @click="view=signer==='supervisor'?'work':'check'">Cancel</button></div><p class="nd-explanation">In the app, signing revalidates access, the exact saved note version, assignments and current Narriva eligibility. This example creates no signature.</p>
    </template>
   </div>
   <aside class="nd-context"><div class="nd-person"><img :src="example.provider.photo" :alt="`Fictional portrait of ${example.provider.name}`" loading="lazy" width="40" height="52"/><div><strong>{{ example.provider.name }}, {{ example.provider.credential }}</strong><span>Assigned provider</span></div></div><h3>Treatment context</h3><p>{{ example.focus }}</p><dl><div><dt>Service</dt><dd>{{ example.encounter.serviceCode==='90847'?'Couples psychotherapy':'Individual psychotherapy' }}</dd></div><div><dt>Frequency</dt><dd>Weekly · Fictional plan</dd></div><div><dt>Plan status</dt><dd>Active example</dd></div></dl><button type="button" @click="view='history'" data-analytics-id="narriva-history">Treatment progress →</button><button type="button" :disabled="!generated" @click="view='summary'" data-analytics-id="narriva-summary">View summary →</button><button type="button" @click="view='work'" data-analytics-id="narriva-work">My Work →</button><small>All identities, scores, notes and results in this walkthrough are fictional.</small></aside>
  </div>
  <footer class="nd-footnote">{{ compact?'Scroll inside the workspace to explore. ':'' }}Actual Narriva components · Synthetic records and scripted results · Clinician judgment and required signatures remain essential.</footer>
 </section>
</template>
<script setup>
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import SmartNotesDemo from './SmartNotesDemo.vue';
import NoteAidObjectiveRatings from '../../components/clinical/NoteAidObjectiveRatings.vue';
import NarrivaModeChooser from '../../components/clinical/NarrivaModeChooser.vue';
import NarrivaCompliancePanel from '../../components/clinical/NarrivaCompliancePanel.vue';
import NarrivaTreatmentHistory from '../../components/clinical/NarrivaTreatmentHistory.vue';
import NarrivaNoteSummary from '../../components/clinical/NarrivaNoteSummary.vue';
import NoteReviewActions from '../../components/clinical/NoteReviewActions.vue';
import { NARRIVA_BRAND, NARRIVA_CHECKS } from '../../config/narrivaBrand.js';
import { NARRIVA_DEMO_AGENCY, NARRIVA_DEMO_NOTICE, NARRIVA_DEMO_INPUT_NOTICE, NARRIVA_DEMO_SOURCE_DISCLOSURE, examplePreviousRatings, narrivaExamples, exampleSections, exampleNarrivaReview, exampleReviewInsights, exampleTreatmentHistory } from '../demo/narriva.js';
const props=defineProps({compact:Boolean,initialView:{type:String,default:'note'},initialMethod:{type:String,default:'narriva'}});
const selected=ref(0),view=ref(props.initialView),method=ref(props.initialMethod),scenario=ref('pass'),corrected=ref(true),review=ref(null),busy=ref(false),providerSigned=ref(false),supervisorSigned=ref(false),signer=ref('provider'),attested=ref(false),announcement=ref(''),revision=ref(0);
const planReviewed=ref(false),ratings=ref([]),ratingKey=ref(0),generated=ref(false);
const previousRatings=computed(()=>examplePreviousRatings(example.value));
const ready=computed(()=>planReviewed.value&&example.value.plan.goals.every(goal=>goal.objectives.every(obj=>ratings.value.some(r=>Number(r.objectiveId)===obj.id&&(r.scaleValue!=null||['deferred','on_hold','not_addressed'].includes(r.disposition))))));
watch(method,()=>{clearState();ratings.value=[];ratingKey.value++;planReviewed.value=false;});
function invalidate(){clearState();}
function updateRatings(value){ratings.value=value;invalidate();}
function generateNote(){if(!ready.value||busy.value)return;scenario.value='pass';corrected.value=true;runChecks(true);}
const steps=[{id:'note',label:'Write a note',analytics:'narriva-write'},{id:'check',label:'Check the note',analytics:'narriva-check-view'},{id:'work',label:'My Work & Quick Sign',analytics:'narriva-work'},{id:'history',label:'Treatment progress',analytics:'narriva-history'}];
const example=computed(()=>narrivaExamples[selected.value]);
const sections=computed(()=>exampleSections(example.value,corrected.value));
const passed=computed(()=>!busy.value&&review.value?.status==='passed'&&review.value?.quickSignEligible===true);
const insights=computed(()=>exampleReviewInsights(example.value.id,NARRIVA_DEMO_AGENCY,sections.value,exampleTreatmentHistory({example:example.value})));
const workItem=computed(()=>({clinicalNoteId:example.value.id,agencyId:NARRIVA_DEMO_AGENCY,narriva:{quickSignEligible:passed.value&&providerSigned.value&&!supervisorSigned.value},updatedAt:revision.value}));
const guidance=computed(()=>({note:'Review the seeded plan, choose three example ratings, then generate the prepared Narriva note.',check:'Choose a complete note or a missing-plan example. Watch all five checks, then review the result.',work:'Quick Sign appears only after the sample passes and its provider signature is simulated.',history:'Review up to five visits, the documented goal and separate client feedback.',summary:'View the saved-note summary and supporting materials.',sign:'Review and attest before a simulated signature.'}[view.value]));
let timer=null,generation=0;
function cancel(){clearTimeout(timer);generation++;busy.value=false;}
function announce(text){announcement.value=text;}
function navigate(target){view.value=target;announcement.value='';attested.value=false;}
function clearState(){cancel();generated.value=false;review.value=null;providerSigned.value=false;supervisorSigned.value=false;attested.value=false;announcement.value='';revision.value++;}
function reset(){clearState();ratings.value=[];ratingKey.value++;planReviewed.value=false;selected.value=0;view.value=props.initialView;method.value='narriva';scenario.value='pass';corrected.value=true;}
function choose(index){clearState();ratings.value=[];ratingKey.value++;planReviewed.value=false;selected.value=index;method.value='narriva';view.value='note';scenario.value='pass';corrected.value=true;}
function changeScenario(value){clearState();generated.value=true;scenario.value=value;corrected.value=value==='pass';view.value='check';}
function runChecks(fromGeneration=false){
 if(!fromGeneration&&!generated.value)return;
 cancel();const current=generation;view.value='check';busy.value=true;attested.value=false;providerSigned.value=false;supervisorSigned.value=false;revision.value++;
 review.value={id:'fictional-running',exampleOnly:true,status:'running',checks:NARRIVA_CHECKS.map(check=>({...check,status:'pending'}))};
 const final=exampleNarrivaReview({passed:corrected.value});final.scoring.criteria[0].evidence=[sections.value.find(section=>section.key==='interventions').text];let index=0;
 function next(){if(current!==generation)return;if(index===NARRIVA_CHECKS.length){review.value=final;busy.value=false;generated.value=true;announce(corrected.value?'Example complete: all five checks pass. Review the note before simulating a signature.':'Example complete: review required. Apply the correction supported by the session source, then run the example again.');return;}review.value={...review.value,checks:review.value.checks.map((check,i)=>({...check,status:i<index?final.checks[i].status:i===index?'running':'pending'}))};announce(`Simulating check ${index+1} of 5: ${NARRIVA_CHECKS[index].label}.`);index++;timer=setTimeout(next,550);}
 next();
}
function applyCorrection(){if(busy.value)return;corrected.value=true;review.value=exampleNarrivaReview({passed:false,stale:true});attested.value=false;providerSigned.value=false;supervisorSigned.value=false;revision.value++;announce('Sample plan updated from the existing session source. The prior result is stale; run the example check again.');}
function beginSignature(kind){if(!generated.value||!passed.value||kind==='supervisor'&&!providerSigned.value)return;signer.value=kind;attested.value=false;view.value='sign';announcement.value='';}
function finishSignature(){if(!attested.value||!passed.value||busy.value||signer.value==='supervisor'&&!providerSigned.value)return;if(signer.value==='supervisor')supervisorSigned.value=true;else providerSigned.value=true;attested.value=false;view.value='work';revision.value++;announce(signer.value==='supervisor'?'Quick Sign simulated. No actual note was co-signed, completed or submitted.':'Provider signature simulated. The sample is now in the supervisor’s My Work; explore Quick Sign.');}
async function loadInsights({noteId,agencyId}){if(noteId!==example.value.id||agencyId!==NARRIVA_DEMO_AGENCY)throw Error('Outside fictional example');return {insights:structuredClone(insights.value)};}
onBeforeUnmount(cancel);
</script>
<style scoped>
